using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define the tools available to the agent
var tools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [AIFunctionFactory.Create(tools.SearchWeb), AIFunctionFactory.Create(tools.TakeNote)],
};

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";

Console.WriteLine($"🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make 2-3 searches with different queries)
        2. Taking notes on key findings using the note-taking tool
        3. After gathering enough information, provide a comprehensive summary

        Always search first, take notes on important findings, then summarize.
        Include sources in your summary.
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var iterationLimit = 10;
var iteration = 0;

await foreach (var update in chatClient.GetStreamingResponseAsync(messages, chatOptions))
{
    Console.Write(update.Text);
    if (++iteration > iterationLimit) break;
}

Console.WriteLine("\n\n📝 Notes collected during research:");
Console.WriteLine(new string('-', 50));
foreach (var note in tools.Notes)
{
    Console.WriteLine($"• {note}");
}

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns search results with titles, snippets, and URLs.")]
    public string SearchWeb([Description("The search query string")] string query)
    {
        // Simulated web search results for demonstration.
        // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
        Console.WriteLine($"\n  🌐 [Searching web: \"{query}\"]\n");

        return $$"""
            Search results for "{{query}}":

            1. Title: "{{query}} - Latest Research Overview"
               URL: https://example.com/research/{{Uri.EscapeDataString(query)}}
               Snippet: Recent studies show significant progress in {{query}}. Researchers have achieved new breakthroughs
               in 2026, with multiple teams publishing findings on improved methodologies and applications.

            2. Title: "{{query}} - Industry Applications"
               URL: https://example.com/industry/{{Uri.EscapeDataString(query)}}
               Snippet: The industry has seen rapid adoption of {{query}} technologies. Major companies are investing
               heavily, with practical applications now emerging across healthcare, finance, and manufacturing.

            3. Title: "{{query}} - Future Directions"
               URL: https://example.com/future/{{Uri.EscapeDataString(query)}}
               Snippet: Experts predict that {{query}} will transform multiple sectors by 2028. Key challenges remain
               in scalability and cost, but recent funding rounds suggest growing confidence in the field.
            """;
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"\n  📌 [Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"]\n");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }
}

